const fs=require('fs'),path=require('path'),puppeteer=require('puppeteer-core');
const axe=require('axe-core');
const BASE='http://127.0.0.1:8000/';
const OUT=process.env.PHASE19_OUT||'/tmp/phase19-baseline';
const routes=['index.html','corporate.html','energy.html','products.html','product.html','urea-46.html','caustic-soda-solid.html','sodium-sulphate-anhydrous.html','sales.html','technology.html','evidence-axis.html','ventures.html','contact.html','privacy.html','legal.html','404.html'];
const perfRoutes=['index.html','corporate.html','energy.html','products.html','sales.html','technology.html','evidence-axis.html','ventures.html','contact.html'];
const views=[[1440,900],[390,844]];
const report={performance:[],accessibility:[],keyboard:[],media:[],film:[],summary:{}};
fs.mkdirSync(OUT,{recursive:true});
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
function classify(mime,url){mime=(mime||'').toLowerCase();if(mime.includes('css'))return'css';if(mime.includes('javascript'))return'js';if(mime.startsWith('image/'))return'image';if(mime.startsWith('video/'))return'video';if(mime.includes('html'))return'document';if(/\.css(?:\?|$)/i.test(url))return'css';if(/\.js(?:\?|$)/i.test(url))return'js';if(/\.(png|jpe?g|webp|svg|gif)(?:\?|$)/i.test(url)||url.includes('images.unsplash.com'))return'image';if(/\.mp4(?:\?|$)/i.test(url))return'video';return'other'}
async function pageWithObservers(browser,w,h){const ctx=await browser.createBrowserContext();const page=await ctx.newPage();await page.setViewport({width:w,height:h,deviceScaleFactor:1});await page.setCacheEnabled(false);await page.evaluateOnNewDocument(()=>{window.__p19={cls:0,lcp:null,fcp:null,longTasks:[]};try{new PerformanceObserver(l=>{for(const e of l.getEntries())window.__p19.cls+=e.hadRecentInput?0:e.value}).observe({type:'layout-shift',buffered:true})}catch{}try{new PerformanceObserver(l=>{const e=l.getEntries().at(-1);if(e)window.__p19.lcp={startTime:e.startTime,size:e.size,element:e.element?.tagName||null}}).observe({type:'largest-contentful-paint',buffered:true})}catch{}try{new PerformanceObserver(l=>{const e=l.getEntries().find(x=>x.name==='first-contentful-paint');if(e)window.__p19.fcp=e.startTime}).observe({type:'paint',buffered:true})}catch{}try{new PerformanceObserver(l=>{for(const e of l.getEntries())window.__p19.longTasks.push({startTime:e.startTime,duration:e.duration})}).observe({type:'longtask',buffered:true})}catch{}});return{ctx,page}}
async function collectLoad(browser,route,w,h,rep=1){const{ctx,page}=await pageWithObservers(browser,w,h);const cdp=await page.target().createCDPSession();await cdp.send('Network.enable');const req=new Map(),errs=[];cdp.on('Network.responseReceived',e=>{req.set(e.requestId,{url:e.response.url,mime:e.response.mimeType,status:e.response.status,fromDisk:e.response.fromDiskCache,fromServiceWorker:e.response.fromServiceWorker,encoded:0})});cdp.on('Network.loadingFinished',e=>{const x=req.get(e.requestId);if(x)x.encoded=e.encodedDataLength||0});page.on('console',m=>{if(m.type()==='error')errs.push('console:'+m.text())});page.on('pageerror',e=>errs.push('page:'+String(e)));page.on('requestfailed',r=>errs.push('request:'+r.url()+':'+(r.failure()?.errorText||'')));const t0=Date.now();let resp=null;try{resp=await page.goto(BASE+route,{waitUntil:'load',timeout:45000})}catch(e){errs.push('nav:'+String(e))}await sleep(route==='index.html'?3000:1200);const timing=await page.evaluate(()=>{const n=performance.getEntriesByType('navigation')[0];const p=window.__p19||{};return{dcl:n?.domContentLoadedEventEnd||null,load:n?.loadEventEnd||null,fcp:p.fcp,lcp:p.lcp,cls:p.cls,longTasks:p.longTasks||[],domBytes:document.documentElement.outerHTML.length,scrollWidth:document.documentElement.scrollWidth,clientWidth:document.documentElement.clientWidth}});const resources=[...req.values()].filter(x=>x.url.startsWith('http'));const agg={requests:resources.length,transfer:0,decoded:0,document:0,css:0,js:0,image:0,video:0,other:0,thirdParty:0};for(const r of resources){agg.transfer+=r.encoded||0;const k=classify(r.mime,r.url);agg[k]=(agg[k]||0)+(r.encoded||0);if(!r.url.startsWith(BASE))agg.thirdParty++}const perfEntries=await page.evaluate(()=>performance.getEntriesByType('resource').map(x=>({name:x.name,transferSize:x.transferSize||0,decodedBodySize:x.decodedBodySize||0,initiatorType:x.initiatorType})));agg.decoded=perfEntries.reduce((a,x)=>a+x.decodedBodySize,0);const largest=[...resources].sort((a,b)=>(b.encoded||0)-(a.encoded||0))[0]||null;const renderBlocking=await page.evaluate(()=>[...document.querySelectorAll('link[rel="stylesheet"],script:not([defer]):not([async])')].map(e=>e.tagName==='LINK'?e.href:(e.src||'[inline]')));const result={route,w,h,rep,status:resp?.status()||0,elapsedMs:Date.now()-t0,...agg,largest,timing,renderBlocking,errors:errs,resources};await ctx.close();return result}
async function auditAxe(browser,route,w,h){const{ctx,page}=await pageWithObservers(browser,w,h);const errs=[];page.on('pageerror',e=>errs.push(String(e)));await page.goto(BASE+route,{waitUntil:'load',timeout:45000});await sleep(450);await page.addScriptTag({content:axe.source});const results=await page.evaluate(async()=>{const r=await axe.run(document,{resultTypes:['violations','incomplete']});const map=x=>x.map(v=>({id:v.id,impact:v.impact,description:v.description,help:v.help,nodes:v.nodes.map(n=>({target:n.target,html:n.html,failureSummary:n.failureSummary}))}));return{violations:map(r.violations),incomplete:map(r.incomplete)}});const counts={critical:0,serious:0,moderate:0,minor:0,unknown:0};for(const v of results.violations)counts[v.impact]!==undefined?counts[v.impact]++:counts.unknown++;const landmarks=await page.evaluate(()=>({main:document.querySelectorAll('main').length,header:document.querySelectorAll('header').length,footer:document.querySelectorAll('footer').length,nav:[...document.querySelectorAll('nav')].map(n=>n.getAttribute('aria-label')||n.getAttribute('aria-labelledby')||'unnamed'),h1:document.querySelectorAll('main h1').length,imgs:[...document.images].map(i=>({src:i.currentSrc||i.src,alt:i.getAttribute('alt'),width:i.getAttribute('width'),height:i.getAttribute('height'),loading:i.getAttribute('loading'),decoding:i.getAttribute('decoding'),fetchpriority:i.getAttribute('fetchpriority')}))}));await ctx.close();return{route,w,h,counts,violations:results.violations,incomplete:results.incomplete,landmarks,errors:errs}}
async function keyboardAudit(browser,route,w,h){const{ctx,page}=await pageWithObservers(browser,w,h);await page.goto(BASE+route,{waitUntil:'load',timeout:45000});await sleep(350);const seq=[];for(let i=0;i<45;i++){await page.keyboard.press('Tab');const f=await page.evaluate(()=>{const e=document.activeElement;if(!e)return null;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return{tag:e.tagName,id:e.id||'',text:(e.getAttribute('aria-label')||e.textContent||'').trim().slice(0,70),href:e.getAttribute('href'),hidden:!!(e.hidden||e.closest('[hidden]')||s.display==='none'||s.visibility==='hidden'),rect:{x:r.x,y:r.y,w:r.width,h:r.height},outline:s.outlineStyle+' '+s.outlineWidth,boxShadow:s.boxShadow}});if(!f)break;seq.push(f);if(f.tag==='BODY')break}const first=seq[0]||null;const hiddenFocus=seq.filter(x=>x.hidden);const tiny=seq.filter(x=>x.rect.w===0||x.rect.h===0);const focusVisible=seq.filter(x=>x.outline&&!/none 0px/.test(x.outline)||x.boxShadow!=='none').length;const skip=await page.evaluate(()=>{const a=document.querySelector('a.skip-link');return a?{exists:true,href:a.getAttribute('href'),text:a.textContent.trim()}: {exists:false}});await ctx.close();return{route,w,h,first,skip,count:seq.length,hiddenFocus: hiddenFocus.length,tinyFocus:tiny.length,focusVisibleCount:focusVisible,sequence:seq}}
async function mediaAudit(browser,route,w,h){const{ctx,page}=await pageWithObservers(browser,w,h);await page.goto(BASE+route,{waitUntil:'load',timeout:45000});await sleep(900);const items=await page.evaluate(async()=>{const vh=innerHeight;const out=[];for(const e of document.querySelectorAll('img,video')){const r=e.getBoundingClientRect();out.push({kind:e.tagName.toLowerCase(),url:e.currentSrc||e.src||'',rendered:[Math.round(r.width),Math.round(r.height)],natural:[e.naturalWidth||e.videoWidth||0,e.naturalHeight||e.videoHeight||0],aboveFold:r.top<vh&&r.bottom>0,loading:e.getAttribute('loading'),decoding:e.getAttribute('decoding'),fetchpriority:e.getAttribute('fetchpriority'),alt:e.getAttribute('alt'),poster:e.getAttribute('poster'),preload:e.getAttribute('preload'),autoplay:e.autoplay,muted:e.muted})}const seen=new Set();for(const e of document.querySelectorAll('body *')){const s=getComputedStyle(e),bg=s.backgroundImage;if(!bg||bg==='none')continue;for(const m of bg.matchAll(/url\(["']?([^"')]+)["']?\)/g)){let u;try{u=new URL(m[1],location.href).href}catch{continue}if(seen.has(u))continue;seen.add(u);const r=e.getBoundingClientRect();let natural=[0,0];try{natural=await new Promise(res=>{const im=new Image();im.onload=()=>res([im.naturalWidth,im.naturalHeight]);im.onerror=()=>res([0,0]);im.src=u})}catch{}out.push({kind:'background',url:u,rendered:[Math.round(r.width),Math.round(r.height)],natural,aboveFold:r.top<vh&&r.bottom>0,loading:'background',decoding:null,fetchpriority:null,alt:null,element:e.className||e.tagName})}}return out});await ctx.close();return{route,w,h,items}}
async function filmAudit(browser,w,h,reduced){const{ctx,page}=await pageWithObservers(browser,w,h);if(reduced)await page.emulateMediaFeatures([{name:'prefers-reduced-motion',value:'reduce'}]);const cdp=await page.target().createCDPSession();await cdp.send('Network.enable');const video=[];const map=new Map();cdp.on('Network.responseReceived',e=>{if((e.response.mimeType||'').startsWith('video/')||/\.mp4(?:\?|$)/i.test(e.response.url)){map.set(e.requestId,{url:e.response.url,status:e.response.status,headers:e.response.headers,encoded:0})}});cdp.on('Network.loadingFinished',e=>{const x=map.get(e.requestId);if(x){x.encoded=e.encodedDataLength||0;video.push(x)}});await page.goto(BASE+'index.html',{waitUntil:'domcontentloaded',timeout:45000});await sleep(2600);const state=await page.evaluate(()=>{const v=document.querySelector('video');return v?{readyState:v.readyState,networkState:v.networkState,currentTime:v.currentTime,paused:v.paused,muted:v.muted,autoplay:v.autoplay,preload:v.preload}:null});await ctx.close();return{w,h,reduced,video,state}}
(async()=>{const browser=await puppeteer.launch({executablePath:process.env.CHROME,headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});try{for(const route of perfRoutes)for(const [w,h] of views)for(let rep=1;rep<=2;rep++)report.performance.push(await collectLoad(browser,route,w,h,rep));for(const route of routes)for(const [w,h] of views)report.accessibility.push(await auditAxe(browser,route,w,h));for(const route of routes)for(const [w,h] of views)report.keyboard.push(await keyboardAudit(browser,route,w,h));for(const route of perfRoutes)for(const [w,h] of views)report.media.push(await mediaAudit(browser,route,w,h));report.film.push(await filmAudit(browser,1440,900,false),await filmAudit(browser,390,844,false),await filmAudit(browser,390,844,true));}finally{await browser.close()}report.summary={performanceCases:report.performance.length,accessibilityContexts:report.accessibility.length,axe:{critical:0,serious:0,moderate:0,minor:0},keyboardContexts:report.keyboard.length,mediaContexts:report.media.length};for(const a of report.accessibility)for(const k of ['critical','serious','moderate','minor'])report.summary.axe[k]+=a.counts[k]||0;fs.writeFileSync(path.join(OUT,'phase19-baseline.json'),JSON.stringify(report,null,2));console.log(JSON.stringify(report.summary,null,2));})();